{
  "narratives": [
    {
      "item_code": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해",
      "start": "p3:L18",
      "end": "p3:L22"
    },
    {
      "item_code": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해",
      "start": "p3:L23",
      "end": "p3:L24"
    },
    {
      "item_code": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거 방법",
      "start": "p3:L25",
      "end": "p3:L32"
    }
  ]
,
  "extras": [
    {
      "after_item": "S6_PERSONAL",
      "title_raw": "가. 인체를 보호하기 위해 필요없는 인원은 멀리 대피시키시오. 누출 지역으로부터 바람이 부는 반대 방향으로 사람들을",
      "reason": "필드없음",
      "statements": [
        {
          "key": "조치",
          "value": "필요없는 인원은 멀리 대피시키시오. 누출 지역으로부터 바람이 부는 반대 방향으로 사람들을"
        ,
          "line": "p3:L18"
        },
        {
          "key": "조치",
          "value": "필요한 조치 사항 및 보호구 대피시키시오. 정화 작업을 하는 동안 적절한 보호 장비와 보호의를 착용할 것. 미스트/증기를"
        ,
          "line": "p3:L19"
        },
        {
          "key": "조치",
          "value": "흡입하지 마시오. 적절한 보호의를 착용하지 않은 경우에는 파손된 용기나 누출물을 만지지 말 것."
        ,
          "line": "p3:L20"
        },
        {
          "key": "조치",
          "value": "적절하게 환기가 되도록 할 것. 누출정도가 심각해서 통제할 수 없다면, 관할기관에 보고해야 함."
        ,
          "line": "p3:L21"
        },
        {
          "key": "참조",
          "value": "개인 보호구에 관한 사항은 MSDS 제8항을 참조할 것."
        ,
          "line": "p3:L22"
        }
      ]
    ,
      "suggested_code": "S6_PERSONAL"
    ,
      "line": "p3:L18"
    },
    {
      "after_item": "S6_ENV",
      "title_raw": "나. 환경을 보호하기 위해 환경으로 배출하지 마시오. 모든 환경적 누출에 대해 적절한 매니저급 또는 관리자급 인원에게",
      "reason": "필드없음",
      "statements": [
        {
          "key": "조치",
          "value": "환경으로 배출하지 마시오. 모든 환경적 누출에 대해 적절한 매니저급 또는 관리자급 인원에게"
        ,
          "line": "p3:L23"
        },
        {
          "key": "조치",
          "value": "필요한 조치사항 통보할 것. 안전하게 처리하는 것이 가능하면, 추가 누설 또는 누출을 방지할 것. 하수도, 수로 또는 지표로 배출하지 마시오."
        ,
          "line": "p3:L24"
        }
      ]
    ,
      "suggested_code": "S6_ENV"
    ,
      "line": "p3:L23"
    },
    {
      "after_item": "S6_CLEANUP",
      "title_raw": "다. 정화 또는 제거 방법 제품이 배수로로 유입되지 않도록 할 것.",
      "reason": "필드없음",
      "statements": [
        {
          "key": "조치",
          "value": "제품이 배수로로 유입되지 않도록 할 것."
        ,
          "line": "p3:L25"
        },
        {
          "key": "대량 누출",
          "value": "대량 누출: 안전하게 처리하는 것이 가능하면 물질의 흐름을 멈추시오. 가능한 경우 누출된 물질"
        ,
          "line": "p3:L26"
        },
        {
          "key": "대량 누출",
          "value": "주위로 도랑을 팔 것. 질석, 마른 모래나 흙에 흡수시켜서 용기에 담을 것. 제품을 수거 후 누출 지역을"
        ,
          "line": "p3:L27"
        },
        {
          "key": "대량 누출",
          "value": "물로 세척할 것."
        ,
          "line": "p3:L28"
        },
        {
          "key": "소량 누출",
          "value": "소량 누출: 흡착성 물질(예. 천, 플리스)로 닦아낼 것. 잔여 오염을 제거하기 위해 표면을 철저히"
        ,
          "line": "p3:L29"
        },
        {
          "key": "소량 누출",
          "value": "세척할 것."
        ,
          "line": "p3:L30"
        },
        {
          "key": "조치",
          "value": "절대로 엎질러 진 것을 다시 사용하려고 본래 용기에 넣지 말 것. 폐기물 처리에 관한 사항은 MSDS"
        ,
          "line": "p3:L31"
        },
        {
          "key": "참조",
          "value": "제13항을 참조할 것."
        ,
          "line": "p3:L32"
        }
      ]
    ,
      "suggested_code": "S6_CLEANUP"
    ,
      "line": "p3:L25"
    }
  ]
}

